  input {
    appearance: none;
    height: 48px;
    margin: 0;
    opacity: 0;
    outline: none;
    position: absolute;
    width: 48px;
    z-index: 1;
    cursor: inherit;
  }

  :host([touch-target='none']) input {
    height: 100%;
    width: 100%;
  }

  .container {
    border-radius: inherit;
    display: flex;
    height: 100%;
    place-content: center;
    place-items: center;
    position: relative;
    width: 100%;
  }

  .outline,
  .background,
  .icon {
    inset: 0;
    position: absolute;
  }

  .outline,
  .background {
    border-radius: inherit;
  }

  .outline {
    border-color: map.get($tokens, 'outline-color');
    border-style: solid;
    border-width: map.get($tokens, 'outline-width');
    box-sizing: border-box;
  }

  .background {
    background-color: map.get($tokens, 'selected-container-color');
