///       'primary60': /* ... */,
///       'primary70': /* ... */,
///       'primary80': /* ... */,
///       'primary90': /* ... */,
///       'primary95': /* ... */,
///       'primary99': /* ... */,
///       // Opt: palette values for:
///       // - secondary
///       // - tertiary
///       // - error
///       // - neutral
///       // - neutral-variant
///     ),
///   );
///
