    // Resizable fields cannot display overflowing content due to `resize` not
    // allowing it.
    overflow: hidden;
  }

  .disabled {
    pointer-events: none;
  }

  slot[name='container'] {
    border-radius: inherit;
  }

  slot[name='container']::slotted(*) {
    border-radius: inherit;
    inset: 0;
    pointer-events: none;
    position: absolute;
  }

