      const signal = task.start();
      task.finish();
      expect(signal.aborted)
        .withContext('finishing a task should not signal an abort')
        .toBeFalse();
    });

    it('should not abort previous tasks when starting after finishing', () => {
      const firstSignal = task.start();
      task.finish();
