    border-radius: map.get($tokens, 'container-shape');
    display: none;
    inset: auto;
    border: none;
    padding: 0px;
    overflow: visible;
    // [popover] adds a canvas background
    background-color: transparent;
    color: inherit;
    opacity: 0;
    z-index: 20;
    position: absolute;
    user-select: none;
    max-height: inherit;
    height: inherit;
    min-width: inherit;
    max-width: inherit;
    scrollbar-width: inherit;
  }

  .menu::backdrop {
    display: none;
