    box-sizing: border-box;
    background-color: map.get($tokens, 'container-color');
    height: inherit;
    max-height: inherit;
    overflow: auto;
    min-width: inherit;
    max-width: inherit;
    border-radius: inherit;
    scrollbar-width: inherit;
  }

  .item-padding {
    padding-block: map.get($tokens, 'top-space')
