    // Arrange
    const root = env.render(
      html`<md-checkbox aria-label="Agree"></md-checkbox>`,
    );

    // Act
    const checkbox = root.querySelector('[aria-label="Agree"]');

    // Assert
    expect(checkbox)
      .withContext('aria attribute query expected to fail without patches')
      .toBeNull();
  });

