function cssWire<T = string>(prop: string, unit = '') {
  return (knob: Knob<T>) => {
    const value =
      knob.latestValue === undefined ? knob.defaultValue : knob.latestValue;
    document.body.style.setProperty(prop, `${value}${unit}`);
  };
}

