  // See https://lit.dev/playground/#gist=febb773565272f75408ab06a0eb49746.
  private renderIndeterminateContainer() {
    return html` <div class="spinner">
      <div class="left">
        <div class="circle"></div>
      </div>
      <div class="right">
        <div class="circle"></div>
      </div>
