function cssCustomPropertyAsNumber(
  knob: Knob<number>,
  val: number,
  container: HTMLElement,
) {
  const value = knob.isUnset ? knob.defaultValue : val;
  if (value) {
    container.style.setProperty(knob.name, String(value));
  } else {
    container.style.removeProperty(knob.name);
  }
}

