              .toBe(10);
          },
        },
        {
          name: 'reset multiple values same name',
          render: () =>
            html`<md-slider
              range
              name="slider"
              value-start="0"
              value-end="10"></md-slider>`,
          change(slider) {
            slider.valueStart = 5;
            slider.valueEnd = 5;
          },
          assertReset(slider) {
            expect(slider.valueStart)
              .withContext('slider.valueStart after reset')
              .toEqual(0);
            expect(slider.valueEnd)
              .withContext('slider.valueEnd after reset')
              .toEqual(10);
          },
        },
        {
          name: 'reset multiple values different names',
          render: () =>
            html`<md-slider
              range
              name-start="slider-start"
              name-end="slider-end"
              value-start="0"
              value-end="10"></md-slider>`,
          change(slider) {
            slider.valueStart = 5;
            slider.valueEnd = 5;
          },
          assertReset(slider) {
            expect(slider.valueStart)
              .withContext('slider.valueStart after reset')
              .toEqual(0);
            expect(slider.valueEnd)
              .withContext('slider.valueEnd after reset')
              .toEqual(10);
          },
        },
      ],
      restoreTests: [
        {
