import {getUndefinedTokens, getUnusedTokens} from './tokens.js';

describe('testing', () => {
  describe('tokens', () => {
    describe('getUnusedTokens()', () => {
      it('should return empty when all tokens are used', () => {
        const styles = css`
          :host {
