    text-wrap: nowrap;
    width: min-content;
  }

  .prefix {
    padding-inline-end: var(--_input-text-prefix-trailing-space);
  }

  .suffix {
    padding-inline-start: var(--_input-text-suffix-leading-space);
  }
}

